questionvariables.text:
validate_numeric(ex) := block([sx], sx: ev(ex, simp), if listofvars(ex) = [] and freeof(%i, sx) then "" else "Type a number in each box, not a letter.");
Srx: matrix([1,0],[0,-1]); Sry: matrix([-1,0],[0,1]); Sryx: matrix([0,1],[1,0]); Srmyx: matrix([0,-1],[-1,0]);
Sr90: matrix([0,-1],[1,0]); Sr180: matrix([-1,0],[0,-1]); Sr270: matrix([0,1],[-1,0]);
symkeys: ["rx","ry","ryx","rmyx","r90","r180","r270"];
symmats: [Srx,Sry,Sryx,Srmyx,Sr90,Sr180,Sr270];
sm(k) := symmats[sublist_indices(symkeys, lambda([u], u=k))[1]];
sn(k) := sublist_indices(symkeys, lambda([u], u=k))[1];
skey(A) := block([j], j: sublist_indices(symmats, lambda([u], is(u=A))), if j=[] then "none" else symkeys[j[1]]);
/* Design: combinations of reflections and turns, with matrices instead of drawing. Source: adapted from SMP Book 5 (Metric), Chapter 13, Exercise F, question 1. Every pair is non-commuting and neither product is the identity. */
plist: [["r270","ryx"],["ry","r270"],["r90","rx"],["ryx","ry"],["rmyx","r90"],["rx","rmyx"],["ryx","r90"],["r90","ryx"],["rmyx","ry"],["ry","ryx"]];
ix: 1+rand(10);
f: plist[ix][1]; s: plist[ix][2];
Fm: sm(f); Sm: sm(s);
ta: Sm.Fm; dop: Fm.Sm;
rk: skey(ta); ok: skey(dop);
opt2: [["id", false, "the identity (no change)"], ["rx", is(rk="rx"), "reflection in the x-axis"], ["ry", is(rk="ry"), "reflection in the y-axis"], ["ryx", is(rk="ryx"), "reflection in the line y = x"], ["rmyx", is(rk="rmyx"), "reflection in the line y = −x"], ["r90", is(rk="r90"), "rotation of 90° anticlockwise about O"], ["r180", is(rk="r180"), "rotation of 180° about O"], ["r270", is(rk="r270"), "rotation of 90° clockwise about O"]];
ta2: first(mcq_correct(opt2));
tw: ta+matrix([1,0],[0,0]);
badm: matrix([q,0],[0,1]);
